DELIMITER //
CREATE PROCEDURE count_registrations(IN p_student_id INT, OUT p_count INT)
SQL SECURITY INVOKER
BEGIN
    SELECT COUNT(*) INTO p_count FROM enrollments WHERE student_id = p_student_id;
END//
DELIMITER ;
CALL count_registrations(108, @n);
SELECT @n AS n ORDER BY n;

DELIMITER //
CREATE FUNCTION pass_label(p_marks INT) RETURNS VARCHAR(12)
DETERMINISTIC NO SQL SQL SECURITY INVOKER
BEGIN
    IF p_marks IS NULL THEN
        RETURN 'pending';
    ELSEIF p_marks >= 40 THEN
        RETURN 'pass';
    END IF;
    RETURN 'fail';
END//
DELIMITER ;
SELECT pass_label(40) AS n ORDER BY n;

